  (p.total?.amount_minor as number) === (((p.tickets ?? []) as readonly any[]).reduce((total: number, ticket) => total + (ticket.price?.amount_minor as number), 0) + (p.fees?.amount_minor as number));
/** urn:corpus:ticketing:order:entity:order — A paid order, with one ticket per held seat or standing place */
export const OrderOrderSchema = v.pipe(
  OrderOrderFields,
  v.forward(v.check(OrderTotalIsPricesPlusFeesRule, "The total must be the sum of the ticket prices plus the fees"), ["total", "amount_minor"]),
);
export type OrderOrder = v.InferOutput<typeof OrderOrderSchema>;
export type OrderOrderInput = v.InferInput<typeof OrderOrderSchema>;

